def _runs(values, minimum):
    """Find maximal runs of indices whose values meet a threshold."""
    result = []
    start = None
    for i, ok in enumerate(values + [False]):
        if ok and start is None:
            start = i
        elif not ok and start is not None:
            if i - start >= minimum:
                result.append((start, i))
            start = None
    return result


def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = set(v for row in grid for v in row)

    # Divider bands are thick colored rows/columns. Detect their positions by
    # near-solid repetition, then sample the crossings of the band centers.
    best = None
    for rail in colors:
        row_scores = [sum(v == rail for v in row) / w for row in grid]
        col_scores = [sum(grid[r][c] == rail for r in range(h)) / h for c in range(w)]
        row_bands = _runs(row_scores, 0.60)
        col_bands = _runs(col_scores, 0.60)
        if len(row_bands) < 2 or len(col_bands) < 2:
            continue
        rnodes = [(a + b - 1) // 2 for a, b in row_bands]
        cnodes = [(a + b - 1) // 2 for a, b in col_bands]

        interiors = [grid[r][c] for r in range(h) for c in range(w)
                     if not any(a <= r < b for a, b in row_bands)
                     and not any(a <= c < b for a, b in col_bands)]
        if not interiors:
            continue
        background = Counter(interiors).most_common(1)[0][0]
        matrix = [[grid[r][c] for c in cnodes] for r in rnodes]
        # On each band crossing, the rail color means ordinary background;
        # other colors are the encoded output markers.
        compact = [[background if v == rail else v for v in row] for row in matrix]
        signals = sum(v != background for row in compact for v in row)
        rank = (len(rnodes) * len(cnodes), signals)
        if best is None or rank > best[0]:
            best = (rank, compact)

    if best is None:
        raise ValueError('No divider bands found')
    return best[1]


